from collections import deque

def comps(g, color, diag=False):
 h,w=len(g),len(g[0]); seen=set(); cs=[]
 steps=[(dr,dc) for dr in [-1,0,1] for dc in [-1,0,1] if (dr or dc) and (diag or abs(dr)+abs(dc)==1)]
 for r in range(h):
  for c in range(w):
   if g[r][c]!=color or (r,c) in seen: continue
   q=[(r,c)]; seen.add((r,c)); cc=[]
   while q:
    x,y=q.pop(); cc.append((x,y))
    for dr,dc in steps:
     p=(x+dr,y+dc)
     if 0<=p[0]<h and 0<=p[1]<w and p not in seen and g[p[0]][p[1]]==color:
      seen.add(p);q.append(p)
   cs.append(cc)
 return sorted(cs,key=len,reverse=True)
