from collections import Counter

PATTERNS = {
    1: [[0, 0, 8], [8, 8, 0], [0, 8, 0]],
    2: [[0, 0, 0], [8, 8, 8], [0, 0, 0]],
    3: [[0, 8, 8], [0, 8, 0], [0, 8, 0]],
}

def transform(grid):
    counts = Counter(cell for row in grid for cell in row if cell != 0)
    dominant = max(counts, key=counts.get)
    return [row[:] for row in PATTERNS[dominant]]
